-- ===== CREATE TABLE (Postgres dialect, no view) =====
CREATE TABLE HST_DateSourceConf (
  AD_Client_ID NUMERIC(10) NOT NULL,
  AD_Org_ID NUMERIC(10) NOT NULL,
  AD_Table_ID NUMERIC(10),
  Created TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  CreatedBy NUMERIC(10),
  HST_DateSourceConf_ID NUMERIC(10) NOT NULL,
  HST_DateSourceConf_UU VARCHAR(36),
  IsActive CHAR(1) DEFAULT 'Y' NOT NULL,
  Script VARCHAR(2000),
  Updated TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  UpdatedBy NUMERIC(10),
  CONSTRAINT hst_datesourceconf_pk PRIMARY KEY (HST_DateSourceConf_ID),
  CONSTRAINT hst_datesourceconf_uu_idx UNIQUE (HST_DateSourceConf_UU)
);

CREATE TABLE HST_UpdCheckConf (
  Description VARCHAR(255),
  HST_UpdCheckConf_UU VARCHAR(36),
  Name VARCHAR(60),
  AD_Client_ID NUMERIC(10) NOT NULL,
  AD_Org_ID NUMERIC(10) NOT NULL,
  AD_Table_ID NUMERIC(10) NOT NULL,
  Created TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CreatedBy NUMERIC(10) NOT NULL,
  HST_CheckQuery VARCHAR(4000),
  HST_CheckUserDef VARCHAR(4000),
  HST_DestTable_ID NUMERIC(10) NOT NULL,
  HST_UpdCheckConf_ID NUMERIC(10) NOT NULL,
  IsActive CHAR(1) DEFAULT 'Y' NOT NULL,
  Updated TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  UpdatedBy NUMERIC(10) NOT NULL,
  CONSTRAINT hst_updcheckconf_pk PRIMARY KEY (HST_UpdCheckConf_ID),
  CONSTRAINT hst_updcheckconf_uu_idx UNIQUE (HST_UpdCheckConf_UU)
);

-- HST_TableRules is a VIEW — skipped (creazione separata)
CREATE TABLE T_HSTCheckResults (
  AD_Client_ID NUMERIC(10) NOT NULL,
  AD_Org_ID NUMERIC(10) NOT NULL,
  AD_PInstance_ID NUMERIC(10),
  AD_Table_ID NUMERIC(10),
  AD_User_ID NUMERIC(10),
  Created TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  CreatedBy NUMERIC(10),
  DateFrom TIMESTAMP WITHOUT TIME ZONE,
  Description VARCHAR(255),
  HST_DestTable_ID NUMERIC(10),
  HST_Record_ID NUMERIC(11),
  IsActive CHAR(1) DEFAULT 'Y' NOT NULL,
  Record_ID CHAR(1),
  T_HSTCheckResults_ID NUMERIC(10) NOT NULL,
  Updated TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  UpdatedBy NUMERIC(10),
  CONSTRAINT t_hstcheckresults_pk PRIMARY KEY (T_HSTCheckResults_ID)
);

-- ===== ALTER TABLE (colonne iniettate su tabelle standard) =====
ALTER TABLE AD_Table ADD COLUMN FIN_ForceOrgZero CHAR(1) DEFAULT 'N' NOT NULL CHECK (FIN_ForceOrgZero IN ('Y','N'));
ALTER TABLE AD_Column ADD COLUMN HST_IsHstColumn CHAR(1) DEFAULT 'N';
ALTER TABLE AD_Process ADD COLUMN AD_InfoWindow_ID NUMERIC(10);
ALTER TABLE AD_Table ADD COLUMN HST_HistoryMode VARCHAR(1) DEFAULT 'N';
ALTER TABLE AD_Table ADD COLUMN HST_IsForceHstApplication CHAR(1) DEFAULT 'N';
ALTER TABLE AD_Tree ADD COLUMN C_Element_ID NUMERIC(10);
ALTER TABLE AD_Tree ADD COLUMN HSTFromDate TIMESTAMP WITHOUT TIME ZONE DEFAULT current_timestamp;
ALTER TABLE AD_Tree ADD COLUMN HSTIsPrimaryTree CHAR(1) DEFAULT 'N';
ALTER TABLE AD_Tree ADD COLUMN HSTParentTree_ID NUMERIC(10);
ALTER TABLE AD_Tree ADD COLUMN HSTToDate TIMESTAMP WITHOUT TIME ZONE DEFAULT current_timestamp;

-- ===== AD_Field iniettati su window standard =====
-- Sub-query dinamica per AD_Tab_ID (gli ID tab standard differiscono tra release).

-- ===== AD_ToolBarButton (HistoryRecords + HistoryRecordsTest) =====
-- Clonati 1:1 da SVI (ID 1000003/1000004 + UU stabili).
-- Cleanup ID provvisori 1000001/1000002 eventualmente inseriti in passato.
DELETE FROM AD_ToolBarButton WHERE AD_ToolBarButton_ID IN (1000001, 1000002);
UPDATE AD_ToolBarButton SET DisplayLogic = '@SQL=select ''Y'' from ad_window inner join ad_tab on ad_window.ad_window_id = ad_tab.ad_window_id inner join ad_table on ad_table.ad_table_id = ad_tab.ad_table_id inner join ad_tab hsttab on hsttab.ad_window_id = ad_window.ad_window_id and hsttab.tablevel = ad_tab.tablevel + 1 and hsttab.seqno > ad_tab.seqno inner join ad_table hsttable on hsttable.ad_table_id = hsttab.ad_table_id where ad_window.ad_window_id=@_WinInfo_AD_Window_ID@ and ad_tab.ad_tab_id = @_TabInfo_AD_Tab_ID@ and ad_table.hst_historymode in (''S'',''T'') and ad_table.tablename||''_HST'' = hsttable.tablename' WHERE AD_ToolBarButton_ID = 1000003;
UPDATE AD_ToolBarButton SET DisplayLogic = '@SQL=select distinct ''Y'' from HST_UpdCheckConf where ad_table_id = @_TabInfo_AD_Table_ID@' WHERE AD_ToolBarButton_ID = 1000004;
